"""Builds the format sys-fmt-cd-panchayatnama-pm-avlokan (owner, पंचायतनामा / PM — 6 parts). Usage: python3 scripts/build_panchayatnama_pm.py out.json
Then merge into assets/seed/formats_seed.json (bump seed_version)."""
import json,sys
keys=[]
def add(name,label,ft='text',dv=None,req=1,**o):
    keys.append({"key_name":name,"label":label,"field_type":ft,"is_required":req,"default_value":dv,
                 "dropdown_options":json.dumps(o,ensure_ascii=False) if o else None,"sort_order":len(keys)+1})
