add('Gender','मृतक या मृतका','dropdown','मृतक',options=["मृतक","मृतका"],hint='पुरुष हो तो "मृतक", महिला हो तो "मृतका" — पूरे लेख में यही शब्द आता है')
add('DName','मृतक / मृतका का नाम',placeholder='जैसे: नेवल किशोर',hint='सिर्फ़ नाम, जैसे: नेवल किशोर')
add('DRel','सम्बन्ध','dropdown','पुत्र',options=["पुत्र","पुत्री","पत्नी"],hint='पिता के नाम से तो पुत्र / पुत्री, पति के नाम से तो पत्नी')
